import { Stock } from "../types/stock";

/**
 * Format raw billions number into friendly market cap string
 */
export function formatMarketCap(numInBillions: number): string {
  if (numInBillions >= 1000) {
    return "$" + (numInBillions / 1000).toFixed(2) + " Trillion";
  }
  return "$" + numInBillions.toFixed(1) + " Billion";
}

/**
 * 11 Standard GICS Corporate Equity Stock Sectors
 */
export const STOCK_SECTORS: string[] = [
  "Information Technology",
  "Health Care",
  "Financials",
  "Consumer Discretionary",
  "Communication Services",
  "Industrials",
  "Consumer Staples",
  "Energy",
  "Utilities",
  "Real Estate",
  "Materials"
];

export const ETF_SECTOR = "ETFs";
export const CRYPTO_SECTOR = "Cryptocurrencies";

export type AssetCategory = 'stocks' | 'etfs' | 'crypto' | 'all';

/**
 * Standard list of all categories present in the universe
 */
export const ALL_SECTORS: string[] = [
  ...STOCK_SECTORS,
  CRYPTO_SECTOR,
  ETF_SECTOR
];

/**
 * Helper to get distinct industries / subIndustries for a sector and asset category
 */
export function getIndustriesForSector(sector: string, assetCategory: AssetCategory = 'stocks'): string[] {
  const set = new Set<string>();
  if (!sector || sector === 'ALL') {
    if (assetCategory === 'stocks') {
      STOCKS_DATA.filter(s => s.sector !== CRYPTO_SECTOR && s.sector !== ETF_SECTOR).forEach(s => {
        if (s.subIndustry) set.add(s.subIndustry);
      });
    } else if (assetCategory === 'etfs') {
      STOCKS_DATA.filter(s => s.sector === ETF_SECTOR).forEach(s => {
        if (s.subIndustry) set.add(s.subIndustry);
      });
    } else if (assetCategory === 'crypto') {
      STOCKS_DATA.filter(s => s.sector === CRYPTO_SECTOR).forEach(s => {
        if (s.subIndustry) set.add(s.subIndustry);
      });
    } else {
      STOCKS_DATA.forEach(s => {
        if (s.subIndustry) set.add(s.subIndustry);
      });
    }
    return Array.from(set).sort();
  }
  STOCKS_DATA.filter(s => s.sector === sector).forEach(s => {
    if (s.subIndustry) set.add(s.subIndustry);
  });
  return Array.from(set).sort();
}

